/* Hallmark · component: terminal dashboard · genre: modern-minimal · theme: warm orange
 * pre-emit critique: P5 H5 E5 S5 R5 V4 · states and focus: Claude Code Button
 */
export type CompactionOutcome =
  | { kind: 'not_run' }
